# id: (headline, lede, [people keys], set key)
A = {
"147691698282": ("Kobe Bryant 1999-00 Bowman's Best #58", "This chromium Kobe card comes from the 1999-00 season, the year Bryant and Shaq brought Los Angeles the first of three straight titles. Shiny, colorful and from the start of a dynasty, it's an easy pick for any Lakers collection.", ["kobe"], "bb9900"),
"147667811713": ("Aaron Judge 2017 National Baseball Card Day Rookie Promo #NYY-2", "Here's an Aaron Judge rookie-year card from 2017, the season he hit 52 homers and won AL Rookie of the Year. These Yankees-only promo cards were handed out at card shops for National Baseball Card Day and never sold in packs, which makes this a nice off-the-beaten-path Judge rookie.", ["judge"], "nbcd17"),
"147681008703": ("Ken Griffey Jr. Tribute to the Kid 2-Card Lot (2016 Topps)", "Two cards from Topps' 2016 Tribute to the Kid insert set, released the summer Griffey was inducted into Cooperstown. The lot includes KID-29 and KID-15, each revisiting a moment from his career. It's an inexpensive way to add some Junior to your binder.", ["griffey"], "t16"),
"147685836090": ("Bill Mazeroski 1962 Topps #353", "Here's Maz on his 1962 Topps card, two seasons after his legendary 1960 World Series home run. 1962 Topps is notorious for chipping on its wood-grain borders, so check the listing photos for this one's exact edges and corners.", ["maz"], "t62"),
"147674449585": ("Whitey Ford 1962 Topps #310", "Whitey Ford's 1962 Topps card follows his 25-4 Cy Young season of 1961, the peak of a Hall of Fame career. The Yankees ace looks right at home inside the classic wood-grain frame.", ["ford"], "t62"),
"147685832214": ("Jacob Misiorowski 2026 Topps Holiday Green Parallel RC #H131", "Here's a green parallel rookie of the Brewers' flamethrower from Topps' festive Holiday release. Colored parallels are produced in smaller quantities than base cards, which makes them a favorite with player collectors.", ["misiorowski"], "t26mlb"),
"147626622752": ("Shaquille O'Neal 1998-99 Bowman's Best #100", "Shaq in Lakers purple and gold during his prime, on Bowman's Best chromium stock. At this price it's an easy add for Lakers and '90s basketball fans.", ["shaq"], "bb9899"),
"147615380408": ("Willie McCovey 1961 Topps #517", "Willie McCovey's 1961 Topps card comes from late in the set and early in a career that ended with 521 home runs and a plaque in Cooperstown. A solid vintage Giants card at a fair price.", ["mccovey"], "t61"),
"147626753806": ("Don Newcombe 1960 Topps #345", "Don Newcombe's 1960 Topps card shows the former Dodgers ace in Cincinnati red. It's an affordable vintage card of a pioneering pitcher with a one-of-a-kind trophy case.", ["newcombe"], "t60"),
"147679056956": ("Cameron Carr 2026 Topps Rookie Hard-Signed Auto #81CRA-CC", "Here's an on-card, hard-signed rookie autograph of Lakers rookie Cameron Carr from Topps' 2026-27 basketball. On-card autos are generally preferred over sticker autos, and a first-year Lakers rookie auto is the kind of card that can look smart years from now.", ["carr"], "t26nba"),
"147681023923": ("1987 Donruss Baseball Pack (16 Cards + Puzzle)", "Take a trip back to 1987 with this Donruss baseball pack, complete with its puzzle pieces. The listing highlights Carl Yastrzemski, and 1987 Donruss, with its black-and-blue borders, is one of the most recognizable designs of the decade.", ["yaz"], "junk"),
"147673783669": ("Alex Bregman 2026 Topps Update Jersey Number Parallel #US25", "This is the headliner of the shop: a 2026 Topps Update Alex Bregman jersey-number parallel in his new Chicago Cubs uniform. Jersey-number parallels are serial-numbered to the player's uniform number, so very few exist. That's why this card carries a premium, and first-year cards on a new team tend to be the ones collectors remember.", ["bregman"], "t26mlb"),
"147614949556": ("Ernie Banks 1960 Topps Sport Magazine All-Star #560", "This high-number All-Star card of Ernie Banks came right after his back-to-back MVP seasons. The Sport Magazine All-Star subset sits in 1960 Topps' scarce high series, so it's harder to find than his base card.", ["banks"], "t60"),
"147638643178": ("Roberto Clemente 1961 Topps #388 (\"Bob\" Clemente)", "Early in his career, Topps called him \"Bob\" Clemente, and this 1961 card is one of the issues that carries that name. It shows him coming off the Pirates' 1960 championship and on the verge of his first batting title. Vintage Clemente cards are always in demand.", ["clemente"], "t61"),
"147679055222": ("Joshua Jefferson 2026 Topps Rookie Auto Gold /50 #283", "Here's a gold rookie autograph of Nets rookie Joshua Jefferson, serial-numbered to just 50 copies. Low-numbered autos from a player's first Topps release are the cards collectors chase.", ["jefferson"], "t26nba"),
"147685840938": ("Mickey Cochrane 1960 Fleer Baseball Greats #24", "This is affordable vintage cardboard of the Hall of Fame catcher, printed in Fleer's cheerful 1960 legends design. It's a great piece for Tigers or Athletics collectors, or anyone building the set.", ["cochrane"], "f60"),
"147679059706": ("Luka Dončić 2026 Topps Hardwood Stars Insert #HS-7", "Luka in Lakers colors on Topps' Hardwood Stars insert. It's one of his first Topps cards as a Laker. Inserts of the league's biggest stars from Topps' return to basketball are hot, and this is a premium example.", ["luka"], "t26nba"),
"147651996643": ("Honus Wagner 1960 Fleer Baseball Greats #62", "You probably can't afford the T206. You can own this genuine 1960s Honus Wagner card from Fleer's Baseball Greats set at a fraction of a fraction of the price. It's a perfect conversation piece and a must for Pirates fans.", ["wagner"], "f60"),
"147662962376": ("Cincy Clouters 1960 Topps #352 (Frank Robinson, Gus Bell, Jerry Lynch)", "This fun combo card spotlights the Reds' sluggers, led by a young Frank Robinson on his way to the 1961 NL MVP. Multi-player cards like this are a hallmark of late-'50s and early-'60s Topps.", ["frobinson"], "t60"),
"147642189382": ("Danny Murtaugh 1961 Topps All-Star #567", "This is a scarce high-number All-Star card of the manager who had just led Pittsburgh past the Yankees in the 1960 World Series. 1961 Topps high numbers were printed in lower quantities and are some of the toughest cards in the set.", ["murtaugh"], "t61"),
"147654727476": ("1962 Topps Homer Kings #401 (Roger Maris & Orlando Cepeda)", "Card #401 honors the 1961 home run leaders: Roger Maris with his record 61 and Orlando Cepeda with 46 to lead the National League. It's a great piece of the most famous home run season of the century.", ["maris", "cepeda"], "t62"),
"147691758968": ("Sports Illustrated Commemorative Issue: 1998 Yankees Champions", "SI's special commemorative issue celebrates the 1998 Yankees, who won 114 regular-season games and swept San Diego in the World Series. Many consider them the greatest team of the modern era. It's a great shelf or frame piece for any Yankees fan.", [], "programs"),
"147585462367": ("1963 Topps Rookie Stars #158", "Multi-player Rookie Stars cards were Topps' way of introducing a crop of young players at once. They're an inexpensive way to own a genuine 1963 card and an important part of completing the set.", [], "t63"),
"147584853234": ("Jimmie Foxx 1961 Fleer Baseball Greats #28", "This is genuine vintage cardboard of one of the great right-handed sluggers in history, at a price that makes it easy to own. A must for Hall of Fame collectors.", ["foxx"], "f61"),
"147637650694": ("Jason Giambi Officially Licensed Yankees Action Photo", "This is an officially licensed action photo of Jason Giambi in pinstripes, ready to frame for a game room or office wall.", ["giambi"], "photofile"),
"147685833997": ("P.J. Washington Jr. 2026-27 Topps Purple Foil /250 #56", "This purple foil parallel of the Mavericks forward is serial-numbered to 250. It's an affordable numbered card for Dallas collectors.", ["pjwashington"], "t26nba"),
"147626739844": ("Orlando Cepeda 1958 Topps Rookie Card #343", "This is the Baby Bull's rookie card, issued in the Giants' first season in San Francisco, the year he won NL Rookie of the Year. Hall of Fame rookie cards from the '50s are cornerstone vintage pieces.", ["cepeda"], "t58"),
"147637910765": ("1935 Germany 100 Reichsmark Banknote", "This circulated 100 Reichsmark note was issued in 1935 by the Reichsbank. It's a striking large-denomination note and a genuine artifact of a dark chapter in 20th-century history, offered uncertified and ungraded.", [], "banknotes"),
"147679057942": ("Yaxel Lendeborg 2026 Topps Rookie Code RC-11", "Here's a Rookie Code insert of Warriors rookie Yaxel Lendeborg from Topps' first 2026-27 basketball release. It's an inexpensive way to get in early on a new Golden State player.", [], "t26nba"),
"147681014484": ("Topps MLB Debut 5-Card Lot (Gray, Bagwell, Price, Yount & more)", "This five-card lot of Topps MLB Debut inserts celebrates the first big-league games of Jeff Bagwell, Robin Yount, David Price and more. It's a fun mix of Hall of Famers and stars at a lot price.", [], "t16"),
"147661840745": ("Roger Maris 1961 Topps #2", "Roger Maris was card #2 in 1961 Topps, the very year he hit 61 home runs to break Babe Ruth's record. It's a centerpiece card from one of baseball's most iconic seasons.", ["maris"], "t61"),
"147692945538": ("2026 Allen & Ginter HOF Legends 7-Card Lot (Ruth, Mantle, Aaron, Griffey)", "This seven-card lot of all-time greats on Allen & Ginter's retro design includes Babe Ruth, Mickey Mantle, Hank Aaron and Ken Griffey Jr. It's a great starter lot for a young collector or a gift.", ["ruth", "aaron", "griffey"], "ag26"),
"147637922586": ("Pascall Energy Corporation Stock Certificate (1,000 Shares)", "This circulated certificate for 1,000 shares of Pascall Energy Corporation has the engraved borders and formal design that make old certificates such good display pieces.", [], "stocks"),
"147651998160": ("Christy Mathewson 1960 Fleer Baseball Greats #2", "Christy Mathewson is card #2 in Fleer's 1960 legends set. It's genuine vintage cardboard of one of the five original Hall of Famers, at a price that's hard to beat.", ["mathewson"], "f60"),
"147662969663": ("Eddie Mathews 1963 Post Cereal #151", "Here's Eddie Mathews cut from the back of a 1963 Post cereal box. The hand-cut edges give every Post card its own personality, and Mathews is one of the set's Hall of Fame highlights.", ["mathews"], "post63"),
"147685827880": ("Jimmy Crooks 2026 Topps Chrome Holiday Plaid Refractor RC #HC15", "This plaid refractor rookie of Cardinals catcher Jimmy Crooks comes from Chrome Holiday. Fun seasonal refractors are produced in limited quantities and are popular with team collectors.", ["crooks"], "t26mlb"),
"147642183763": ("Nellie Fox 1961 Topps All-Star #570", "This high-number All-Star card shows Nellie Fox fresh off his 1959 MVP and the White Sox pennant. 1961 Topps high numbers are among the scarcest cards of the decade.", ["fox"], "t61"),
"147673788432": ("Roy McMillan 1962 Topps All-Star #393", "This 1962 Topps National League All-Star card shows one of the best defensive shortstops of the '50s. It's an inexpensive way to fill an All-Star subset slot.", ["mcmillan"], "t62"),
"147681010393": ("Kyle Schwarber 2016 Topps Berger's Best Rookie Reprint #BB2-2016", "Schwarber's rookie season, done up in a vintage design as part of Topps' Berger's Best insert. A fun Cubs card from the year they won it all.", ["schwarber"], "t16"),
"147681021413": ("Topps 2016 5-Card Lot: Berger's Best & Hallowed Highlights (incl. Clemente)", "This five-card lot of 2016 Topps commemorative inserts includes a Roberto Clemente. Berger's Best and Hallowed Highlights both celebrate the game's history with thoughtful designs.", ["clemente"], "t16"),
"147614852123": ("Orlando Cepeda 1962 Topps Sporting News All-Star #390", "Here's Orlando Cepeda on a 1962 All-Star card, earned with his monster 1961 season when he led the NL in homers and RBIs. A great vintage Giants card.", ["cepeda"], "t62"),
"147614841415": ("Red Schoendienst 1958 Topps #190", "This card shows Red Schoendienst with the Milwaukee Braves, fresh off their 1957 championship. It's a nice Hall of Fame card from a landmark Topps year.", ["schoendienst"], "t58"),
"147681883497": ("1971 New York Mets Official Yearbook", "This official 1971 Mets yearbook comes from the era just after the '69 Miracle Mets, with Tom Seaver, Jerry Koosman and company. Vintage team yearbooks are full of photos and ads that capture Shea Stadium at its peak.", [], "programs"),
"147639139772": ("1955 World Series Brooklyn Dodgers Rain Check Ticket Stub", "This is a genuine piece of the most cherished moment in Brooklyn baseball history. In 1955 the Dodgers finally beat the Yankees to win their only World Series in Brooklyn, behind Johnny Podres' Game 7 shutout. Original 1955 World Series ticket material from Ebbets Field is genuinely rare, and this rain check stub is the kind of item serious Dodgers and New York collectors build displays around.", ["podres"], "tickets"),
"147661830603": ("Duke Snider 1961 Topps #443", "Here's the Duke in a Los Angeles Dodgers uniform on his 1961 Topps card. He remained a key bat for the club after its move west. A classic Hall of Fame card at a reasonable price.", ["snider"], "t61"),
"147674461781": ("Don Drysdale 1962 Topps #340", "This is Don Drysdale's card from 1962, his Cy Young Award season, with the iconic wood-grain borders. A sharp vintage Dodgers card.", ["drysdale"], "t62"),
"147585452344": ("Willie Mays 1962 Topps All-Star #395", "This is a 1962 Topps All-Star card of the Say Hey Kid at the height of his powers. Any vintage Willie Mays card is a cornerstone piece, and the All-Star card is an affordable way to own one.", ["mays"], "t62"),
"147615024573": ("Grover Cleveland Alexander 1960 Fleer Baseball Greats #5", "Old Pete is pictured here on Fleer's 1960 legends set. It's affordable vintage cardboard of a 373-game winner.", ["alexander"], "f60"),
"147651994155": ("Eddie Mathews 1954 Bowman #64", "This 1954 Bowman card shows Eddie Mathews in his early Milwaukee years, right after his 47-homer breakout in 1953. It's a terrific vintage Hall of Fame card from the Bowman-Topps rivalry era.", ["mathews"], "bow54"),
"147615536000": ("Bram Stoker's Dracula #1 (Topps Comics, 1992) with Cards", "Topps Comics' official adaptation of the 1992 Coppola film features Mike Mignola artwork a few years before Hellboy made him a legend. This copy includes the trading cards 1-4 that came with the issue.", [], "comics"),
"147637909910": ("Yogi Berra 1961 Topps #425", "Here's Yogi in 1961, when the Yankees won 109 games and the World Series. It's a classic card of one of the most beloved figures the game has ever had.", ["berra"], "t61"),
"147665666963": ("1959 Fleer Ted Williams 3-Card Lot", "This three-card lot comes from Fleer's 1959 set devoted entirely to Ted Williams' life and career. These cards tell his story one moment at a time, and a lot is a great way to start the set.", ["williams"], "f59"),
"147679064122": ("Christian Anderson Jr. 2026-27 Topps The Daily Dribble RC #DD-37", "This rookie insert from Topps' 2026-27 flagship comes from The Daily Dribble set, which spotlights the new class. It's an early card of a new NBA guard.", ["anderson"], "t26nba"),
"147681017957": ("Jason Heyward 2016 Topps Wrigley Field 100 Years 2-Card Lot", "Two Jason Heyward cards from Topps' 2016 insert celebrating 100 years at Wrigley Field, released the same year the Cubs finally won it all.", ["heyward"], "t16"),
"147626715683": ("Lou Brock 1964 Topps #29", "Lou Brock's 1964 Topps card shows him with the Cubs, issued the same year Chicago traded him to St. Louis in one of the most lopsided deals ever. Brock went on to a Hall of Fame career, which makes this a fun historical card.", ["brock"], "t64"),
"147627834338": ("2017 National Baseball Card Day Yankees Sealed Pack (Ruth & Judge)", "This sealed Yankees pack from Topps' 2017 National Baseball Card Day promotion features Babe Ruth and Aaron Judge, the old and new faces of the franchise. Sealed promo packs from this event are getting harder to find.", ["ruth", "judge"], "nbcd17"),
"147637659842": ("Derek Jeter Photo File 8x10 (Officially Licensed)", "This officially licensed 8x10 photo of the Yankees captain is ready to frame.", ["jeter"], "photofile"),
"147692955261": ("Ashton Jeanty 2025 Panini Mosaic Rookie Variation Red Scope Prizm #287", "Here's a Red Scope Prizm rookie variation of the Raiders' prized running back from 2025 Mosaic. Colored prizm parallels are the heart of the modern football market.", ["jeanty"], "modern_fb"),
"147661837322": ("Harmon Killebrew 1961 Topps #80", "Harmon Killebrew's 1961 card comes from the year the Senators moved to Minnesota and became the Twins. It's a solid Hall of Fame card at a fair price.", ["killebrew"], "t61"),
"147679069998": ("Anthony Edwards 2026-27 Topps Drivers Blue Rainbow /150 #DR-27", "This Blue Rainbow parallel of Ant-Man is numbered to 150, from Topps' Drivers insert. It's a numbered insert of one of the most marketable stars in the league.", ["edwards"], "t26nba"),
"147691437110": ("1988 Fleer Baseball Logo Stickers & Update Cards Box (132 Cards)", "This box of 1988 Fleer cards and team logo stickers is a nostalgic snapshot of late-'80s baseball, great for a trip down memory lane or as a gift for a young collector.", [], "junk"),
"147614150743": ("Jim Brown 1961 Philadelphia #41", "This is a genuine early-'60s card of football's greatest runner, from the Philadelphia Gum set. Vintage Jim Brown cards are always in demand, and this one is from the heart of his career.", ["jimbrown"], "phil61"),
"147637898861": ("1963 Topps Friendly Foes #68 (Duke Snider & Gil Hodges)", "This combo card unites two Brooklyn Dodgers legends, Duke Snider and Gil Hodges. Both were Hall of Famers and longtime teammates.", ["snider", "hodges"], "t63"),
"147638774790": ("1998 Yankees vs. Mariners Ticket Stub (Yankee Stadium)", "This original ticket stub comes from the historic 1998 season, when the Yankees won 125 games including the postseason. It's an affordable piece of a legendary year.", [], "tickets"),
"147614947867": ("Hank Aaron 1960 Topps #300", "Hank Aaron is card #300 in 1960 Topps, following his 1959 NL batting title in Milwaukee. Vintage Aaron cards are blue-chip pieces for any collection.", ["aaron"], "t60"),
"147637927054": ("International Leisure & Casino Common Stock Certificate", "This circulated common stock certificate from International Leisure & Casino is a fun display piece for game rooms and anyone who collects casino or Las Vegas memorabilia.", [], "stocks"),
"147661835489": ("Luis Aparicio 1961 Topps #440", "Little Looie's 1961 card comes from just after the White Sox' 1959 pennant run, when he was in the middle of his nine-year stolen-base reign. A great affordable Hall of Famer.", ["aparicio"], "t61"),
"147674456874": ("Jim Perry 1962 Topps #405", "This 1962 Topps card shows Jim Perry with Cleveland, years before his 1970 Cy Young season in Minnesota.", ["jperry"], "t62"),
"147684081989": ("Ken Boyer 1962 Topps #370", "Ken Boyer's 1962 card shows him two years before his MVP and championship season of 1964. A Cardinals favorite at a nice price.", ["boyer"], "t62"),
"147639888763": ("Alexandria Ocasio-Cortez and the Freshman Force: New Party (Devil's Due)", "Devil's Due's comic casts the congresswoman as a superhero in a tongue-in-cheek political adventure. This copy is in new (other) condition. Its oddball subject made it a talked-about release, and it's a fun piece of pop-culture publishing.", [], "comics"),
"147642193503": ("Don Drysdale 1964 Topps #120", "This is Big D's 1964 Topps card, coming off the Dodgers' 1963 sweep of the Yankees. A nice vintage Dodgers Hall of Famer.", ["drysdale"], "t64"),
"147584873349": ("Roy Campanella 1956 Topps #101", "Campy is pictured here on 1956 Topps, often called the best-looking baseball set of all time. The card follows his third MVP and the Dodgers' 1955 championship, which makes it a key card for Brooklyn collectors.", ["campanella"], "t56"),
"147626728858": ("Jim Kaat 1963 Topps #165", "This is a 1963 Topps card of the 283-game winner and 16-time Gold Glover, who was finally voted into Cooperstown in 2022.", ["kaat"], "t63"),
"147690076548": ("Chris Cenac Jr. 2026-27 Topps Flagship Rookie Foil #282", "This foil parallel rookie card of Celtics big man Chris Cenac Jr. comes from Topps' 2026-27 flagship. It's an inexpensive way in on a new Boston rookie.", ["cenac"], "t26nba"),
"147638637332": ("Orlando Cepeda 1961 Topps #435", "Here's Cepeda on 1961 Topps, the year he led the NL with 46 homers and 142 RBIs. A fair-priced vintage Giants star.", ["cepeda"], "t61"),
"147661854304": ("Eddie Mathews 1961 Topps #120", "Here's the Braves' slugging third baseman on his 1961 Topps card, from the middle of his 512-homer career.", ["mathews"], "t61"),
"147681887422": ("1988 New York Mets Calendar: Shea Stadium 25th Anniversary", "This 1988 Mets calendar celebrates 25 years of Shea Stadium and features stars like Gary Carter and Dwight Gooden from the '86 championship core. It's a great nostalgic piece for Mets fans.", [], "programs"),
"147627877197": ("International Mint .999 Fine Silver Krugerrand Commemorative (2g)", "This small 2-gram commemorative piece from International Mint is struck in .999 fine silver. Note that it's a commemorative design inspired by the famous Krugerrand, not a South African Mint bullion coin. It's a nice little silver piece and gift idea.", [], "coins"),
"147637628132": ("Yogi Berra Daily News Newspaper Insert", "This vintage-style Daily News insert celebrates Yogi Berra's career in pinstripes.", ["berra"], "dailynews"),
"147638627654": ("Pedro Martinez 1998 Topps Gold Label Class 2 #45", "This 1998 Gold Label card captures Pedro in his first year with Boston, right after his 1997 Cy Young with Montreal. Gold Label's thick, foil-stamped stock still looks premium today.", ["pedro"], "nineties"),
"147690081520": ("Shai Gilgeous-Alexander 2026 Topps Stars of the NBA #SNBA-34", "This Stars of the NBA insert features the reigning MVP and champion. It's an affordable card of the league's best player right now.", ["sga"], "t26nba"),
"147585458310": ("1978 Topps League Leaders #206: 1977 Strikeout Leaders (Niekro & Ryan)", "This league-leaders card pairs two Hall of Famers, Phil Niekro and Nolan Ryan, who led their leagues in strikeouts in 1977. It's an inexpensive vintage Nolan Ryan card.", ["niekro", "ryan"], "t78"),
}
